@patch
def claim(self:Queue,
          worker:str='worker',  # who is holding the lease; recorded on the row and in history
          n:int=1,              # how many jobs to take
          now:float=None
) -> L:
    "Claim up to `n` due jobs in one statement; no job was claimed twice over 400 jobs and 8 processes (`evals/jobs.py`)."
    now = time.time() if now is None else now
    with write_txn(self.db):
        rows = self.db.q(
            'UPDATE jobs SET state=?, worker=?, lease_until=?, updated_at=? WHERE id IN '
            '(SELECT id FROM jobs WHERE state=? AND run_at<=? ORDER BY priority, run_at LIMIT ?) '
            'RETURNING *', ['running', worker, now + self.lease, now, 'ready', now, n])
    # RETURNING gives no defined row order; ORDER BY in the subquery only picks which rows
    return L(sorted(rows, key=lambda r: (r['priority'], r['run_at']))).map(_row)

@patch
def _held(self:Queue, job) -> dict|None:
    "The row as it stands, or None if this worker no longer holds it. Call inside a `write_txn`."
    cur = first(self.db.q('SELECT * FROM jobs WHERE id=?', [job['id']]))
    if cur is None or cur['state'] != 'running' or cur['worker'] != job.get('worker'): return None
    return cur

@patch
def ack(self:Queue, job) -> AttrDict:
    "Mark a claimed job done, or return it as `lost` when this worker's lease was reclaimed."
    with write_txn(self.db):
        if self._held(job) is None: return _row(dict(job, state='lost'))
        self.db.q('UPDATE jobs SET state=?, error=NULL, worker=NULL, lease_until=0, updated_at=? WHERE id=?',
                  ['done', time.time(), job['id']])
    return _row(dict(job, state='done'))

@patch
def fail(self:Queue,
         job,                # the claimed job
         error:str,          # what went wrong; truncated to 500 chars on the row
         after:float=None,   # seconds until the retry; None uses `backoff`
         dead:bool=False     # dead-letter now, whatever the attempts left: retrying a 401 never turns into success
) -> AttrDict:
    "Record a failure and schedule a retry after the backoff delay, or mark the job dead once its attempts are spent."
    now, err = time.time(), str(error)[:500]
    with write_txn(self.db):
        if (cur := self._held(job)) is None: return _row(dict(job, state='lost'))
        att = cur['attempt'] + 1
        dead = dead or att >= (cur['max_attempts'] or self.max_attempts)
        nxt = cur['run_at'] if dead else now + (backoff(att, base=self.base) if after is None else after)
        self.db.q('UPDATE jobs SET state=?, attempt=?, run_at=?, error=?, worker=NULL, lease_until=0, '
                  'updated_at=? WHERE id=?', ['dead' if dead else 'ready', att, nxt, err, now, cur['id']])
    return _row(dict(cur, state='dead' if dead else 'ready', attempt=att, run_at=nxt, error=err))

@patch
def reclaim(self:Queue, now:float=None) -> L:
    "Fail each running job whose lease expired with `lease expired`; this counts one attempt, and the job is dead after `max_attempts`."
    now = time.time() if now is None else now
    exp = self.db.q('SELECT * FROM jobs WHERE state=? AND lease_until>0 AND lease_until<=?', ['running', now])
    # two pollers can read the same expired row; the check in `fail` lets only one of them count it
    return L(exp).map(lambda j: self.fail(j, 'lease expired')).filter(lambda j: j['state'] != 'lost')

