ENDED = ('done', 'failed', 'stopped', 'closed')
RUN = uuid.uuid4().hex[:12]   # this process; `close_running` closes the running rows of any other one
_LCOLS = ('key', 'kind', 'state', 'title', 'said', 'start', 'end', 'url', 'obj', 'why', 'seen', 'quiet', 'run', 'ver')

def _lrow(r) -> AttrDict|None:
    "A ledger row as an `AttrDict`: its `meta` keys merged in, and `seen` and `quiet` as bools."
    if r is None: return None
    d = {k: v for k, v in dict(r).items() if k != 'meta'}
    return AttrDict({**json.loads(r.get('meta') or '{}'), **d, 'seen': bool(d.get('seen')), 'quiet': bool(d.get('quiet'))})

class Ledger:
    "Rows for jobs that run elsewhere, such as an in-process future: their state, a progress line and a change counter."
    def __init__(self,
                 db,                      # open litesearch/fastlite Database; the rows live in its file
                 keep:float=172800,       # seconds an ended row stays, 2 days
                 run:str=None,            # the id of this process; None -> `RUN`
                 busy_ms:int=BUSY_TIMEOUT_MS):
        store_attr()
        self.run = run or RUN
        self.db.conn.set_busy_timeout(busy_ms)
        self.t = self.db.t.job_ledger
        with write_txn(self.db):
            self.t.create(key=str, kind=str, state=str, title=str, said=str, start=float, end=float, url=str, obj=str,
                          why=str, seen=int, quiet=int, run=str, ver=int, meta=str, pk='key', if_not_exists=True)
            self.db.t.job_ledger_ver.create(id=int, n=int, pk='id', if_not_exists=True)
            self.db.conn.execute('CREATE INDEX IF NOT EXISTS job_ledger_state ON job_ledger(state, "end")')

    @property
    def version(self) -> int:
        "A count that goes up at each write of a row, in any process."
        return (first(self.db.q('SELECT n FROM job_ledger_ver WHERE id=1')) or {}).get('n') or 0

    def __repr__(self):
        n = first(self.db.q("SELECT count(*) n FROM job_ledger WHERE state='running'"))['n']
        return f'Ledger({n} running, version {self.version})'

