@patch
def _bump(self:Ledger) -> int:
    "The next version. Call inside a `write_txn`."
    return first(self.db.q('INSERT INTO job_ledger_ver(id, n) VALUES (1, 1) '
                           'ON CONFLICT(id) DO UPDATE SET n=n+1 RETURNING n'))['n']

@patch
def get(self:Ledger, key:str) -> AttrDict|None:
    "The row `key`, or None."
    return _lrow(first(self.db.q('SELECT * FROM job_ledger WHERE key=?', [key])))

@patch
def put(self:Ledger, key:str, **kv) -> AttrDict:
    "Merge `kv` into the row `key`, and make the row when it is new. A key that is not a column goes in `meta`."
    with write_txn(self.db):
        cur = first(self.db.q('SELECT * FROM job_ledger WHERE key=?', [key])) or dict(seen=0, quiet=0, run=self.run)
        meta = {**json.loads(cur.get('meta') or '{}'), **{k: v for k, v in kv.items() if k not in _LCOLS}}
        row = {**{k: v for k, v in cur.items() if k != 'meta'}, **{k: v for k, v in kv.items() if k in _LCOLS}}
        row.update(key=key, ver=self._bump(), meta=json.dumps(meta, default=str),
                   seen=int(bool(row.get('seen'))), quiet=int(bool(row.get('quiet'))))
        self.t.insert(row, replace=True)
    return _lrow(row)

@patch
def start(self:Ledger, key:str, kind:str, title:str='', said:str='', url:str='', obj:str='', quiet:bool=False, **meta) -> AttrDict:
    "Write the row `key` of a job of `kind` that runs now. Ended rows older than `keep` go."
    self.purge()
    return self.put(key, kind=kind, title=title, said=said, url=url, obj=obj, quiet=quiet, state='running',
                    start=time.time(), end=None, why='', seen=False, run=self.run, **meta)

@patch
def end(self:Ledger, key:str, state:str='done', why:str='', **kv) -> AttrDict|None:
    "End the row `key` now in `state`, with `why` for a failure. None when there is no row."
    if self.get(key) is None: return None
    return self.put(key, state=state, end=time.time(), why=why, **kv)

@patch
def rows(self:Ledger, state:str=None, kind:str=None, obj:str=None) -> L:
    "The rows, newest first, filtered by `state`, `kind` and `obj`."
    w = [(c, v) for c, v in (('state', state), ('kind', kind), ('obj', obj)) if v is not None]
    sql = 'SELECT * FROM job_ledger' + (' WHERE ' + ' AND '.join(f'{c}=?' for c, _ in w) if w else '') + ' ORDER BY start DESC'
    return L(self.db.q(sql, [v for _, v in w])).map(_lrow)

@patch
def purge(self:Ledger, before:float=None) -> int:
    "Delete the ended rows that ended before `before`, by default `keep` seconds ago. Return the count."
    cut = time.time() - self.keep if before is None else before
    with write_txn(self.db): return len(self.db.q(f'DELETE FROM job_ledger WHERE state IN ({",".join("?"*len(ENDED))}) '
                                                  'AND "end"<? RETURNING key', [*ENDED, cut]))

