@patch
def track(self:Ledger,
          kind:str,         # what the job is
          fut,              # a `concurrent.futures.Future`, or a function that returns one, called after the row is written
          key:str=None,     # the row; None -> a new key, which the future has as `fut.key`
          ok=None,          # `ok(result) -> dict`: more keys for the row when it ends, and `state` to end in another state
          why=None,         # `why(error) -> str`: the line of a failure
          **meta            # `title`, `said`, `url`, `obj`, `quiet`, and any other keys of the row
):
    "Write a `running` row for the future `fut`, and end it when `fut` ends. Return the future."
    key = key or f'{kind}:{uuid.uuid4().hex[:12]}'
    self.start(key, kind, **meta)
    if callable(fut): fut = fut()
    try: fut.key = key
    except AttributeError: pass
    def _end(f):
        try:
            if (r := self.get(key)) is None or r.state != 'running': return
            if (e := f.exception()) is not None: self.end(key, 'failed', why=why(e) if why else f'{type(e).__name__}: {str(e)[:200]}')
            else:
                kv = dict((ok(f.result()) or {}) if ok else {})
                self.end(key, kv.pop('state', 'done'), **kv)
        except Exception: pass   # a row that cannot be written never breaks the job
    fut.add_done_callback(_end)
    return fut

@patch
def say(self:Ledger, key:str, line:str) -> bool:
    "Write the progress line `line` to the row `key` while its job runs. Whether the row changed."
    try:
        if (r := self.get(key)) is None or r.state != 'running' or r.said == line: return False
        self.put(key, said=line); return True
    except Exception: return False

