@patch
def close_running(self:Ledger) -> int:
    "Mark `closed` each running row that another process wrote. Return the count."
    ks = self.db.q("SELECT key FROM job_ledger WHERE state='running' AND (run IS NULL OR run!=?)", [self.run])
    for r in ks: self.end(r['key'], 'closed')
    self.purge()
    return len(ks)

@patch
def seen(self:Ledger, obj:str) -> int:
    "Mark each ended row of the object `obj` as seen. Return the count that changed."
    ks = [r.key for r in self.rows(obj=obj) if r.state in ENDED and not r.seen]
    for k in ks: self.put(k, seen=True)
    return len(ks)

@patch
def activity(self:Ledger,
             fresh:float=21600,   # seconds an ended row shows until it is seen, 6 hours
             now:float=None) -> L:
    "The running rows, newest first, then the rows that ended in the last `fresh` seconds and are not seen, newest first."
    now, rs = now or time.time(), self.rows().filter(lambda r: not r.quiet)
    run = rs.filter(lambda r: r.state == 'running')
    new = sorted((r for r in rs if r.state in ('done', 'failed', 'closed') and not r.seen and now - (r.end or 0) < fresh),
                 key=lambda r: -(r.end or 0))
    return run + L(new)
